package com.company.onlineschool;
import com.company.onlineschool.controller.*; import com.company.onlineschool.dto.*; import com.company.onlineschool.entity.*; import com.company.onlineschool.exception.*; import com.company.onlineschool.service.SchoolService;
import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.*; import org.junit.runner.RunWith; import org.mockito.*; import org.mockito.junit.MockitoJUnitRunner; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@RunWith(MockitoJUnitRunner.class)
public class ControllerContractTest {
 @Mock private SchoolService service; private MockMvc mvc; private final ObjectMapper json=new ObjectMapper();
 @Before public void init(){mvc=MockMvcBuilders.standaloneSetup(new CourseController(service),new StudentController(service)).setControllerAdvice(new GlobalExceptionHandler()).build();}
 @Test public void postCourseReturns201() throws Exception {CourseResponse r=new CourseResponse();r.setCourseId(1L);r.setCourseName("Java");r.setCourseDescription("Basics");r.setCredits(4);r.setMessage("Course created successfully");when(service.createCourse(any())).thenReturn(r);mvc.perform(post("/courses").contentType(MediaType.APPLICATION_JSON).content("{\"courseName\":\"Java\",\"courseDescription\":\"Basics\",\"credits\":4}")).andExpect(status().isCreated()).andExpect(jsonPath("$.courseId").value(1)).andExpect(jsonPath("$.message").value("Course created successfully"));}
 @Test public void postCourseRejectsInvalidCredits() throws Exception {mvc.perform(post("/courses").contentType(MediaType.APPLICATION_JSON).content("{\"courseName\":\"Java\",\"courseDescription\":\"Basics\",\"credits\":0}")).andExpect(status().isBadRequest());}
 @Test public void postStudentReturns201AndCourse() throws Exception {Course c=new Course();c.setCourseId(7L);c.setCourseName("Java");Student s=new Student();s.setStudentId(2L);s.setFirstName("Asha");s.setLastName("Rao");s.setEmail("asha@school.test");s.setCourse(c);when(service.createStudent(eq(7L),any())).thenReturn(s);mvc.perform(post("/students/7").contentType(MediaType.APPLICATION_JSON).content("{\"firstName\":\"Asha\",\"lastName\":\"Rao\",\"email\":\"asha@school.test\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.studentId").value(2)).andExpect(jsonPath("$.course.courseId").value(7));}
 @Test public void postStudentRejectsInvalidEmail() throws Exception {mvc.perform(post("/students/7").contentType(MediaType.APPLICATION_JSON).content("{\"firstName\":\"Asha\",\"lastName\":\"Rao\",\"email\":\"bad\"}")).andExpect(status().isBadRequest());}
 @Test public void getStudentReturns200() throws Exception {Student s=new Student();s.setStudentId(2L);when(service.getStudent(2L)).thenReturn(s);mvc.perform(get("/students/2")).andExpect(status().isOk()).andExpect(jsonPath("$.studentId").value(2));}
 @Test public void unknownResourceReturns404() throws Exception {when(service.getStudent(99L)).thenThrow(new ResourceNotFoundException("Student not found: 99"));mvc.perform(get("/students/99")).andExpect(status().isNotFound()).andExpect(jsonPath("$.status").value(404));}
 @Test public void duplicateEmailReturns409() throws Exception {when(service.createStudent(eq(7L),any())).thenThrow(new DuplicateEmailException("Email already exists"));mvc.perform(post("/students/7").contentType(MediaType.APPLICATION_JSON).content("{\"firstName\":\"Asha\",\"lastName\":\"Rao\",\"email\":\"asha@school.test\"}")).andExpect(status().isConflict());}
}
